"""Public API surface of ``sktime.libs.kronos``."""

import inspect

import pytest

import sktime.libs.kronos as kronos_package
from sktime.libs.kronos import kronos as kronos_module

PACKAGE_EXPORTS = [
    "Kronos",
    "KronosPredictor",
    "KronosTokenizer",
    "auto_regressive_inference",
    "sample_from_logits",
    "top_k_top_p_filtering",
]

MODULE_EXPORTS = sorted(PACKAGE_EXPORTS + ["calc_time_stamps"])

MODULE_COMPONENTS = [
    "BSQuantizer",
    "DependencyAwareLayer",
    "DualHead",
    "HierarchicalEmbedding",
    "RMSNorm",
    "TemporalEmbedding",
    "TransformerBlock",
]


def _params(func):
    return list(inspect.signature(func).parameters)


def _defaults(func):
    return {
        name: param.default
        for name, param in inspect.signature(func).parameters.items()
        if param.default is not inspect.Parameter.empty
    }


def test_package_all_is_exact():
    """The package exposes exactly the documented public objects."""
    assert list(kronos_package.__all__) == PACKAGE_EXPORTS


def test_package_exports_resolve_to_module_attributes():
    """Every advertised package export is the object defined in the module."""
    for name in PACKAGE_EXPORTS:
        assert getattr(kronos_package, name) is getattr(kronos_module, name)


def test_module_all_lists_helper_that_package_does_not_export():
    """``calc_time_stamps`` is a module level helper, not a package export."""
    assert sorted(kronos_module.__all__) == MODULE_EXPORTS
    assert hasattr(kronos_module, "calc_time_stamps")
    assert not hasattr(kronos_package, "calc_time_stamps")


@pytest.mark.parametrize(
    "name", ["Kronos", "KronosTokenizer", "KronosPredictor"]
)
def test_public_model_objects_are_classes(name):
    assert inspect.isclass(getattr(kronos_module, name))


@pytest.mark.parametrize(
    "name", ["auto_regressive_inference", "sample_from_logits", "top_k_top_p_filtering"]
)
def test_public_functions_are_functions(name):
    assert inspect.isfunction(getattr(kronos_module, name))


def test_tokenizer_hyperparameter_signature():
    """Tokenizer accepts the documented architecture hyperparameters in order."""
    assert _params(kronos_module.KronosTokenizer.__init__)[1:] == [
        "d_in",
        "d_model",
        "n_heads",
        "ff_dim",
        "n_enc_layers",
        "n_dec_layers",
        "ffn_dropout_p",
        "attn_dropout_p",
        "resid_dropout_p",
        "s1_bits",
        "s2_bits",
        "beta",
        "gamma0",
        "gamma",
        "zeta",
        "group_size",
    ]


def test_kronos_hyperparameter_signature():
    assert _params(kronos_module.Kronos.__init__)[1:] == [
        "s1_bits",
        "s2_bits",
        "n_layers",
        "d_model",
        "n_heads",
        "ff_dim",
        "ffn_dropout_p",
        "attn_dropout_p",
        "resid_dropout_p",
        "token_dropout_p",
        "learn_te",
    ]


