{"command": "cd /testbed; cat > tests/sktime/libs/timer_s1/test_ts_generation_mixin.py <<'PYEOF'
"""Tests for :mod:`sktime.libs.timer_s1.ts_generation_mixin`.

``TSGenerationMixin`` adapts the Hugging Face generation loop to time-series
patches.  The generation loop itself is exercised through the model class; here
the observable contract of the mixin is tested: bookkeeping of the model
keyword arguments between generation steps, and re-normalisation of forecast
samples in :meth:`TSGenerationMixin.generate`.
"""

import importlib
import importlib.util

import numpy as np
import pytest

MIXIN_MODULE = "sktime.libs.timer_s1.ts_generation_mixin"

_HAS_MODEL_STACK = (
    importlib.util.find_spec("torch") is not None
    and importlib.util.find_spec("transformers") is not None
)
requires_model_stack = pytest.mark.skipif(
    not _HAS_MODEL_STACK,
    reason="torch and transformers are required to run the generation loop",
)


class _Array(np.ndarray):
    """Array with the handful of methods the mixin calls on tensors."""

    def new_ones(self, shape):
        return np.ones(shape, dtype=self.dtype).view(_Array)

    def unsqueeze(self, dim):
        return np.expand_dims(self, axis=dim).view(_Array)

    def to(self, device):
        return self


class _CatOnlyTorch:
    """Stand-in for the ``torch`` module restricted to concatenation."""

    @staticmethod
    def cat(tensors, dim=0):
        return np.concatenate([np.asarray(t) for t in tensors], axis=dim).view(_Array)


class _ModelOutput:
    """Minimal stand-in for a Hugging Face ``ModelOutput``."""

    def __init__(self, **fields):
        self._fields = dict(fields)

    def __contains__(self, key):
        return key in self._fields

    def __getattr__(self, name):
        try:
            return self._fields[name]
        except KeyError:
            raise AttributeError(name) from None


def _tensor(values, dtype=np.float64):
    return np.asarray(values, dtype=dtype).view(_Array)


@pytest.fixture
def mixin(monkeypatch):
    """Yield a mixin instance whose torch usage is backed by numpy arrays."""
    module = importlib.import_module(MIXIN_MODULE)
    monkeypatch.setattr(module, "torch", _CatOnlyTorch)
    return module.TSGenerationMixin()


def test_mixin_extends_huggingface_generation_mixin():
    module = importlib.import_module(MIXIN_MODULE)

    assert issubclass(module.TSGenerationMixin, module.GenerationMixin)


def test_known_cache_names_are_tracked_for_kwarg_updates():
    module = importlib.import_module(MIXIN_MODULE)

    assert module.ALL_CACHE_NAMES == [
        "past_key_values",
        "cache_params",
        "state",
        "mems",
        "past_buckets_states",
    ]


def test_attention_mask_is_extended_by_the_generated_horizon(mixin):
    model_kwargs = {"attention_mask": _tensor([[1.0, 1.0, 0.0]])}

    mixin._update_model_kwargs_for_generation(
        _ModelOutput(), model_kwargs, horizon_length=2
    )

    assert model_kwargs["attention_mask"].shape == (1, 5)
    assert model_kwargs["attention_mask"].tolist() == [[1.0, 1.0, 0.0, 1.0, 1.0]]


def test_kwargs_mapping_is_updated_in_place(mixin):
    model_kwargs = {"attention_mask": _tensor([[1.0, 1.0]])}

    returned = mixin._update_model_kwargs_for_generation(
        _ModelOutput(), model_kwargs, horizon_length=1
    )

    assert returned is model_kwargs


def test_token_type_ids_are_extended_with_the_last_value(mixin):
    model_kwargs = {"token_type_ids": _tensor([[0, 1]], dtype=np.int64)}

    mixin._update_model_kwargs_for_generation(
        _ModelOutput(), model_kwargs, horizon_length=2
    )

    assert model_kwargs["token_type_ids"].tolist() == [[0, 1, 1, 1]]


def test_cache_position_advances_by_the_horizon(mixin):
    model_kwargs = {"cache_position": _tensor([3], dtype=np.int64)}

    mixin._update_model_kwargs_for_generation(
        _ModelOutput(), model_kwargs, horizon_length=4
    )

    assert model_kwargs["cache_position"].tolist() == [7]


def test_absent_cache_position_is_not_created(mixin):
    model_kwargs = {}

    mixin._update_model_kwargs_for_generation(
        _ModelOutput(), model_kwargs, horizon_length=2
    )

    assert "cache_position" not in model_kwargs


def test_past_key_values_are_carried_over_from_model_outputs(mixin):
    model_kwargs = {"past_key_values": "old-cache"}

    mixin._update_model_kwargs_for_generation(
        _ModelOutput(past_key_values="new-cache"),
        model_kwargs,
        horizon_length=1,
    )

    assert model_kwargs["past_key_values"] == "new-cache"


def test_legacy_cache_names_are_mapped_to_past_key_values(mixin):
    model_kwargs = {}

    mixin._update_model_kwargs_for_generation(
        _ModelOutput(mems="recurrent-state"), model_kwargs, horizon_length=1
    )

    assert model_kwargs["past_key_values"] == "recurrent-state"
    assert "mems" not in model_kwargs


def test_encoder_decoder_generation_extends_the_decoder_attention_mask(mixin):
    model_kwargs = {
        "decoder_attention_mask": _tensor([[1.0, 1.0]]),
        "attention_mask": _tensor([[1.0, 1.0]]),
    }

    mixin._update_model_kwargs_for_generation(
        _ModelOutput(), model_kwargs, horizon_length=1, is_encoder_decoder=True
    )

    assert model_kwargs["decoder_attention_mask"].tolist() == [[1.0, 1.0, 1.0]]
    assert model_kwargs["attention_mask"].tolist() == [[1.0, 1.0]]


def test_mtp_hidden_states_are_stored_on_the_first_step(mixin):
    hidden_states = _tensor(np.zeros((2, 3, 4)))
    model_kwargs = {}

    mixin._update_model_kwargs_for_generation(
        _ModelOutput(hidden_states_for_mtp=hidden_states),
        model_kwargs,
        horizon_length=1,
    )

    assert model_kwargs["full_hidden_states"].shape == (2, 3, 4)


def test_mtp_hidden_states_are_accumulated_across_steps(mixin):
    model_kwargs = {}
    mixin._update_model_kwargs_for_generation(
        _ModelOutput(hidden_states_for_mtp=_tensor(np.zeros((2, 3, 4)))),
        model_kwargs,
        horizon_length=1,
    )

    mixin._update_model_kwargs_for_generation(
        _ModelOutput(hidden_states_for_mtp=_tensor(np.ones((2, 1, 4)))),
        model_kwargs,
        horizon_length=1,
    )

    accumulated = model_kwargs["full_hidden_states"]
    assert accumulated.shape == (2, 4, 4)
    assert np.allclose(accumulated[:, -1, :], 1.0)


def test_mtp_hidden_states_are_ignored_when_the_output_has_none(mixin):
    model_kwargs = {}

    mixin._update_model_kwargs_for_generation(
        _ModelOutput(hidden_states_for_mtp=None), model_kwargs, horizon_length=1
    )

    assert "full_hidden_states" not in model_kwargs


def test_absent_mtp_output_leaves_kwargs_untouched(mixin):
    model_kwargs = {"attention_mask": _tensor([[1.0]])}

    mixin._update_model_kwargs_for_generation(
        _ModelOutput(), model_kwargs, horizon_length=1
    )

    assert "full_hidden_states" not in model_kwargs


@requires_model_stack
def test_generate_rejects_non_sequential_inputs(monkeypatch):
    torch = pytest.importorskip("torch")
    module = importlib.import_module(MIXIN_MODULE)

    with pytest.raises(ValueError, match="Input shape must be"):
        module.TSGenerationMixin().generate(inputs=torch.zeros(2, 3, 4))


@requires_model_stack
def test_generate_normalises_inputs_and_restores_the_input_scale(monkeypatch):
    torch = pytest.importorskip("torch")
    module = importlib.import_module(MIXIN_MODULE)
    captured = {}

    def _fake_generate(self, inputs=None, **kwargs):
        captured["inputs"] = inputs.detach().clone()
        captured["kwargs"] = kwargs
        return inputs.clone()

    monkeypatch.setattr(module.GenerationMixin, "generate", _fake_generate)
    inputs = torch.tensor([[1.0, 2.0, 3.0, 4.0], [10.0, 20.0, 30.0, 40.0]])

    outputs = module.TSGenerationMixin().generate(inputs=inputs)

    normalised = captured["inputs"]
    assert torch.allclose(normalised.mean(dim=-1), torch.zeros(2), atol=1e-6)
    assert torch.allclose(
        normalised.std(dim=-1, unbiased=False), torch.ones(2), atol=1e-4
    )
    assert torch.allclose(outputs, inputs, atol=1e-6)


@requires_model_stack
def test_generate_without_revin_forwards_inputs_unchanged(monkeypatch):
    torch = pytest.importorskip("torch")
