"""Tests for timesfm in-context covariate regression helpers."""

import numpy as np
import pytest

import sktime.libs.timesfm.xreg_lib as xreg_lib
from sktime.libs.timesfm.xreg_lib import (
    BatchedInContextXRegBase,
    BatchedInContextXRegLinear,
    _repeat,
    _to_padded_jax_array,
    _unnest,
)


class _FakeRandom:
    @staticmethod
    def PRNGKey(seed):
        return seed

    @staticmethod
    def choice(key, n, shape, replace=False):
        assert replace is False
        return np.arange(shape[0]) % n


class _FakeDefaultDevice:
    def __init__(self, device):
        self.device = device

    def __enter__(self):
        return None

    def __exit__(self, *args):
        return False


class _FakeJax:
    random = _FakeRandom
    default_device = _FakeDefaultDevice


